def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for the full separator rows and columns.
    counts = {}
    for row in grid:
        if row[0] != 0 and all(v == row[0] for v in row):
            counts[row[0]] = counts.get(row[0], 0) + 1
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            counts[color] = counts.get(color, 0) + 1
    if not counts:
