    sep = max(counts, key=counts.get)

    sep_rows = [r for r in range(h) if all(v == sep for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    def ranges(n, separators):
        out, start = [], 0
        for p in separators:
            if start < p:
                out.append((start, p))
            start = p + 1
        if start < n:
            out.append((start, n))
        return out

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)
    if not row_ranges or not col_ranges:
