    tile_w = col_ranges[0][1] - col_ranges[0][0]
    nr, nc = len(row_ranges), len(col_ranges)

    # Record each color's occupied local coordinates in every tile.
    patterns = {}
    for tr, (r0, r1) in enumerate(row_ranges):
