                        patterns.setdefault(color, {}).setdefault((tr, tc), set()).add((r-r0, c-c0))

    out = [row[:] for row in grid]

    def flip(pattern, height, width, vertical=False, horizontal=False):
        result = set()
        for r, c in pattern:
            if vertical:
                r = height - 1 - r
            if horizontal:
                c = width - 1 - c
            result.add((r, c))
        return result

    for color, tiles in patterns.items():
