                corners = [(tr, tc), (tr, tc+1), (tr+1, tc), (tr+1, tc+1)]
                present = [p for p in corners if p in tiles]
                if len(present) != 3:
                    continue

                # Reflections only apply to equal-sized, full tiles.
                heights = [row_ranges[tr][1] - row_ranges[tr][0],
                           row_ranges[tr+1][1] - row_ranges[tr+1][0]]
                widths = [col_ranges[tc][1] - col_ranges[tc][0],
