                    is_right = pos[1] == tc + 1
                    normalized.append(flip(tiles[pos], th, tw, is_bottom, is_right))
                if not all(p == normalized[0] for p in normalized[1:]):
                    continue

                missing = next(p for p in corners if p not in tiles)
                is_bottom = missing[0] == tr + 1
                is_right = missing[1] == tc + 1
                completed = flip(normalized[0], th, tw, is_bottom, is_right)
